import AppKit

/// Agent logos for the tab sidebar and title, as SVG (macOS 14 draws SVG data). Taken from
/// agmux (remote-relay/public/icons); agents without one show no logo.
enum AgentLogo {
    private static var cache: [String: NSImage] = [:]

    /// The logo for an agent ID (`AgentKind.id`), or nil.
    static func image(for agent: String) -> NSImage? {
        if let hit = cache[agent] { return hit }
        guard let svg = svgs[agent], let image = NSImage(data: Data(svg.utf8)) else { return nil }
        cache[agent] = image
        return image
    }

